  2	
  3	import com.fasterxml.jackson.core.JsonProcessingException;
  4	import com.fasterxml.jackson.databind.ObjectMapper;
  5	import com.fasterxml.jackson.databind.SerializationFeature;
  6	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  7	import com.pousadamarealta.api.*;
  8	import com.pousadamarealta.exception.*;
  9	import com.pousadamarealta.infrastructure.Database;
 10	import com.pousadamarealta.repository.MessageRepository;
 11	import com.pousadamarealta.repository.ReservationRepository;
 12	import com.pousadamarealta.repository.RoomRepository;
 13	import com.pousadamarealta.service.MessageService;
 14	import com.pousadamarealta.service.ReportService;
 15	import com.pousadamarealta.service.ReservationService;
 16	import io.javalin.Javalin;
 17	import io.javalin.json.JavalinJackson;
 18	import javax.sql.DataSource;
 19	
 20	public class App {
 21	    public static void main(String[] args) {
 22	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 23	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 24	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 25	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 26	
 27	        DataSource dataSource = Database.initialize(dbUrl, dbUser, dbPassword);
 28	
 29	        RoomRepository roomRepository = new RoomRepository(dataSource);
 30	        ReservationRepository reservationRepository = new ReservationRepository(dataSource);
 31	        MessageRepository messageRepository = new MessageRepository(dataSource);
 32	
 33	        roomRepository.initializeRooms();
 34	
 35	        MessageService messageService = new MessageService(messageRepository);
 36	        ReservationService reservationService = new ReservationService(
 37	            reservationRepository, roomRepository, messageService
 38	        );
 39	        ReportService reportService = new ReportService(reservationRepository);
 40	
 41	        RoomController roomController = new RoomController(roomRepository);
 42	        ReservationController reservationController = new ReservationController(reservationService);
 43	        MessageController messageController = new MessageController(messageService);
 44	        ReportController reportController = new ReportController(reportService);
 45	
 46	        ObjectMapper objectMapper = new ObjectMapper();
 47	        objectMapper.registerModule(new JavaTimeModule());
 48	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 49	
 50	        Javalin app = Javalin.create(config -> {
 51	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 52	        });
 53	
 54	        app.get("/rooms", roomController::getAllRooms);
 55	
 56	        app.post("/reservations", reservationController::createReservation);
 57	        app.get("/reservations/{id}", reservationController::getReservation);
 58	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 59	        app.post("/reservations/{id}/check-in", reservationController::checkInReservation);
 60	        app.post("/reservations/{id}/check-out", reservationController::checkOutReservation);
 61	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 62	        app.get("/reservations/{id}/document", reservationController::getDocument);
 63	
 64	        app.get("/messages", messageController::getAllMessages);
 65	
 66	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 67	        app.get("/reports/revenue", reportController::getRevenueReport);
 68	
 69	        app.exception(InvalidRequestException.class, ExceptionHandler::handleInvalidRequest);
 70	        app.exception(RoomNotFoundException.class, ExceptionHandler::handleRoomNotFound);
 71	        app.exception(ReservationNotFoundException.class, ExceptionHandler::handleReservationNotFound);
 72	        app.exception(RoomUnavailableException.class, ExceptionHandler::handleRoomUnavailable);
 73	        app.exception(OperationNotAllowedException.class, ExceptionHandler::handleOperationNotAllowed);
 74	        app.exception(CapacityExceededException.class, ExceptionHandler::handleCapacityExceeded);
 75	        app.exception(JsonProcessingException.class, ExceptionHandler::handleJsonProcessing);
 76	        app.exception(Exception.class, ExceptionHandler::handleGenericException);
 77	
 78	        app.start(port);
 79	
 80	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 81	            app.stop();
 82	            Database.shutdown();
 83	        }));
 84	    }
 85	}
 86	package com.pousadamarealta.api;
 87	
 88	import com.pousadamarealta.api.dto.*;
 89	import com.pousadamarealta.domain.RatePlanType;
 90	import com.pousadamarealta.domain.Reservation;
 91	import com.pousadamarealta.exception.InvalidRequestException;
 92	import com.pousadamarealta.service.ReservationService;
 93	import io.javalin.http.Context;
 94	import java.time.LocalDate;
 95	import java.time.format.DateTimeParseException;
 96	
 97	public class ReservationController {
 98	    private final ReservationService reservationService;
 99	
100	    public ReservationController(ReservationService reservationService) {
101	        this.reservationService = reservationService;
102	    }
103	
104	    public void createReservation(Context ctx) {
105	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
106	
107	        validateRequest(request);
108	
109	        RatePlanType ratePlanType = parseRatePlan(request.ratePlan());
110	
111	        Reservation reservation = reservationService.createReservation(
112	            request.roomNumber(),
113	            request.guestName(),
114	            request.guestEmail(),
115	            request.guestCpf(),
116	            request.checkIn(),
117	            request.checkOut(),
118	            request.guests(),
119	            ratePlanType,
120	            request.companyCode()
121	        );
122	
123	        ctx.status(201).json(ReservationDTO.from(reservation));
124	    }
125	
126	    public void getReservation(Context ctx) {
127	        long id = parseId(ctx);
128	        Reservation reservation = reservationService.getReservation(id);
129	        ctx.json(ReservationDTO.from(reservation));
130	    }
131	
132	    public void confirmReservation(Context ctx) {
133	        long id = parseId(ctx);
134	        Reservation reservation = reservationService.confirmReservation(id);
135	        ctx.json(ReservationDTO.from(reservation));
136	    }
137	
138	    public void checkInReservation(Context ctx) {
139	        long id = parseId(ctx);
140	        Reservation reservation = reservationService.checkInReservation(id);
141	        ctx.json(ReservationDTO.from(reservation));
142	    }
143	
144	    public void checkOutReservation(Context ctx) {
145	        long id = parseId(ctx);
146	        Reservation reservation = reservationService.checkOutReservation(id);
147	        ctx.json(DocumentDTO.from(reservation));
148	    }
149	
150	    public void cancelReservation(Context ctx) {
151	        long id = parseId(ctx);
152	        Reservation reservation = reservationService.cancelReservation(id);
153	        ctx.json(ReservationDTO.from(reservation));
154	    }
155	
156	    public void getDocument(Context ctx) {
157	        long id = parseId(ctx);
158	        Reservation reservation = reservationService.getReservation(id);
159	
160	        if (!reservation.isPaid()) {
161	            throw new InvalidRequestException("Document only available for paid reservations");
162	        }
163	
164	        ctx.json(DocumentDTO.from(reservation));
165	    }
166	
167	    private void validateRequest(CreateReservationRequest request) {
168	        if (request.roomNumber() == null || request.roomNumber().isEmpty()) {
169	            throw new InvalidRequestException("Room number is required");
170	        }
171	        if (request.guestName() == null || request.guestName().isEmpty()) {
172	            throw new InvalidRequestException("Guest name is required");
173	        }
174	        if (request.guestEmail() == null || request.guestEmail().isEmpty()) {
175	            throw new InvalidRequestException("Guest email is required");
176	        }
177	        if (request.guestCpf() == null || request.guestCpf().isEmpty()) {
178	            throw new InvalidRequestException("Guest CPF is required");
179	        }
180	        if (request.checkIn() == null) {
181	            throw new InvalidRequestException("Check-in date is required");
182	        }
183	        if (request.checkOut() == null) {
184	            throw new InvalidRequestException("Check-out date is required");
185	        }
186	        if (request.checkOut().isBefore(request.checkIn()) ||
187	            request.checkOut().equals(request.checkIn())) {
188	            throw new InvalidRequestException("Check-out must be after check-in");
189	        }
190	        if (request.guests() < 1) {
191	            throw new InvalidRequestException("At least one guest is required");
192	        }
193	        if (request.ratePlan() == null || request.ratePlan().isEmpty()) {
194	            throw new InvalidRequestException("Rate plan is required");
195	        }
196	    }
197	
198	    private RatePlanType parseRatePlan(String ratePlan) {
199	        try {
200	            return RatePlanType.valueOf(ratePlan);
201	        } catch (IllegalArgumentException e) {
202	            throw new InvalidRequestException("Invalid rate plan: " + ratePlan);
203	        }
204	    }
205	
206	    private long parseId(Context ctx) {
207	        try {
208	            return Long.parseLong(ctx.pathParam("id"));
209	        } catch (NumberFormatException e) {
210	            throw new InvalidRequestException("Invalid reservation ID");
211	        }
212	    }
213	}
