237	package com.pousadamarealta.api;
238	
239	import com.pousadamarealta.exception.InvalidRequestException;
240	import com.pousadamarealta.service.ReportService;
241	import io.javalin.http.Context;
242	import java.time.LocalDate;
243	import java.time.YearMonth;
244	import java.time.format.DateTimeFormatter;
245	import java.time.format.DateTimeParseException;
246	
247	public class ReportController {
248	    private final ReportService reportService;
249	
250	    public ReportController(ReportService reportService) {
251	        this.reportService = reportService;
252	    }
253	
254	    public void getOccupancyReport(Context ctx) {
255	        String dateParam = ctx.queryParam("date");
256	
257	        if (dateParam == null || dateParam.isEmpty()) {
258	            throw new InvalidRequestException("Date parameter is required");
259	        }
260	
261	        LocalDate date;
262	        try {
263	            date = LocalDate.parse(dateParam, DateTimeFormatter.ISO_LOCAL_DATE);
264	        } catch (DateTimeParseException e) {
265	            throw new InvalidRequestException("Invalid date format. Use YYYY-MM-DD");
266	        }
267	
268	        String csv = reportService.generateOccupancyReport(date);
269	
270	        ctx.contentType("text/csv; charset=utf-8")
271	           .result(csv);
272	    }
273	
274	    public void getRevenueReport(Context ctx) {
275	        String monthParam = ctx.queryParam("month");
276	
277	        if (monthParam == null || monthParam.isEmpty()) {
278	            throw new InvalidRequestException("Month parameter is required");
279	        }
280	
281	        YearMonth month;
282	        try {
283	            month = YearMonth.parse(monthParam, DateTimeFormatter.ofPattern("yyyy-MM"));
284	        } catch (DateTimeParseException e) {
285	            throw new InvalidRequestException("Invalid month format. Use YYYY-MM");
286	        }
287	
288	        String csv = reportService.generateRevenueReport(month);
289	
290	        ctx.contentType("text/csv; charset=utf-8")
291	           .result(csv);
292	    }
293	}
