317	package com.pousadamarealta.api;
318	
319	import com.fasterxml.jackson.core.JsonProcessingException;
320	import com.pousadamarealta.api.dto.ErrorResponse;
321	import com.pousadamarealta.exception.*;
322	import io.javalin.http.Context;
323	import io.javalin.http.HttpStatus;
324	
325	public class ExceptionHandler {
326	
327	    public static void handleInvalidRequest(InvalidRequestException e, Context ctx) {
328	        ctx.status(HttpStatus.BAD_REQUEST)
329	           .json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
330	    }
331	
332	    public static void handleRoomNotFound(RoomNotFoundException e, Context ctx) {
333	        ctx.status(HttpStatus.NOT_FOUND)
334	           .json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
335	    }
336	
337	    public static void handleReservationNotFound(ReservationNotFoundException e, Context ctx) {
338	        ctx.status(HttpStatus.NOT_FOUND)
339	           .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
340	    }
341	
342	    public static void handleRoomUnavailable(RoomUnavailableException e, Context ctx) {
343	        ctx.status(HttpStatus.CONFLICT)
344	           .json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
345	    }
346	
347	    public static void handleOperationNotAllowed(OperationNotAllowedException e, Context ctx) {
348	        ctx.status(HttpStatus.CONFLICT)
349	           .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
350	    }
351	
352	    public static void handleCapacityExceeded(CapacityExceededException e, Context ctx) {
353	        ctx.status(HttpStatus.UNPROCESSABLE_CONTENT)
354	           .json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
355	    }
356	
357	    public static void handleJsonProcessing(JsonProcessingException e, Context ctx) {
358	        ctx.status(HttpStatus.BAD_REQUEST)
359	           .json(new ErrorResponse("INVALID_REQUEST", "Invalid JSON format"));
360	    }
361	
362	    public static void handleGenericException(Exception e, Context ctx) {
363	        e.printStackTrace();
364	        ctx.status(HttpStatus.INTERNAL_SERVER_ERROR)
365	           .json(new ErrorResponse("INTERNAL_ERROR", "An internal error occurred"));
366	    }
367	}

