199	
200	public class Reservation {
201	    private Long id;
202	    private final String roomNumber;
203	    private final RoomType roomType;
204	    private final String guestName;
205	    private final String guestEmail;
206	    private final String guestCpf;
207	    private final LocalDate checkIn;
208	    private final LocalDate checkOut;
209	    private final int guests;
210	    private final RatePlanType ratePlanType;
211	    private final long nights;
212	    private final BigDecimal subtotal;
213	    private final BigDecimal discount;
214	    private final BigDecimal total;
215	    private ReservationStatus status;
216	    private BigDecimal amountPaid;
217	    private BigDecimal refund;
218	
219	    public Reservation(Long id, String roomNumber, RoomType roomType, String guestName,
220	                      String guestEmail, String guestCpf, LocalDate checkIn, LocalDate checkOut,
221	                      int guests, RatePlanType ratePlanType, long nights, BigDecimal subtotal,
222	                      BigDecimal discount, BigDecimal total, ReservationStatus status,
223	                      BigDecimal amountPaid, BigDecimal refund) {
224	        this.id = id;
225	        this.roomNumber = roomNumber;
226	        this.roomType = roomType;
227	        this.guestName = guestName;
228	        this.guestEmail = guestEmail;
229	        this.guestCpf = guestCpf;
230	        this.checkIn = checkIn;
231	        this.checkOut = checkOut;
232	        this.guests = guests;
233	        this.ratePlanType = ratePlanType;
234	        this.nights = nights;
235	        this.subtotal = subtotal;
236	        this.discount = discount;
237	        this.total = total;
238	        this.status = status;
239	        this.amountPaid = amountPaid;
240	        this.refund = refund;
241	    }
242	
243	    public static Reservation create(String roomNumber, Room room, String guestName,
244	                                    String guestEmail, String guestCpf, LocalDate checkIn,
245	                                    LocalDate checkOut, int guests, RatePlanType ratePlanType,
246	                                    String companyCode) {
247	        RatePlan ratePlan = RatePlanFactory.create(ratePlanType);
248	        ratePlan.validate(checkIn, checkOut, companyCode);
249	
250	        long nights = PriceCalculator.calculateNights(checkIn, checkOut);
251	        BigDecimal subtotal = ratePlan.calculateSubtotal(room, checkIn, checkOut);
252	        BigDecimal discount = ratePlan.calculateDiscount(subtotal);
253	        BigDecimal total = subtotal.subtract(discount);
254	
255	        return new Reservation(
256	            null,
257	            roomNumber,
258	            room.getType(),
259	            guestName,
260	            guestEmail,
261	            guestCpf,
262	            checkIn,
263	            checkOut,
264	            guests,
265	            ratePlanType,
266	            nights,
267	            subtotal,
268	            discount,
269	            total,
270	            ReservationStatus.PENDING,
271	            BigDecimal.ZERO,
272	            null
273	        );
274	    }
275	
276	    public void confirm() {
277	        if (status != ReservationStatus.PENDING) {
278	            throw new OperationNotAllowedException("Can only confirm pending reservations");
279	        }
280	        this.status = ReservationStatus.CONFIRMED;
281	        this.amountPaid = this.total;
282	    }
283	
284	    public void checkIn() {
285	        if (status != ReservationStatus.CONFIRMED) {
286	            throw new OperationNotAllowedException("Can only check in confirmed reservations");
287	        }
288	        this.status = ReservationStatus.CHECKED_IN;
289	    }
290	
291	    public void checkOut() {
292	        if (status != ReservationStatus.CHECKED_IN) {
293	            throw new OperationNotAllowedException("Can only check out after check-in");
294	        }
295	        this.status = ReservationStatus.CHECKED_OUT;
296	    }
297	
298	    public void cancel() {
299	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
300	            throw new OperationNotAllowedException("Can only cancel pending or confirmed reservations");
301	        }
302	
303	        RatePlan ratePlan = RatePlanFactory.create(ratePlanType);
304	        this.refund = ratePlan.calculateRefund(amountPaid);
