235	import java.math.BigDecimal;
236	import java.text.NumberFormat;
237	import java.time.LocalDate;
238	import java.time.format.DateTimeFormatter;
239	import java.util.Locale;
240	
241	public class DocumentFormatter {
242	    private static final Locale PT_BR = new Locale("pt", "BR");
243	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
244	    private static final NumberFormat CURRENCY_FORMATTER = NumberFormat.getCurrencyInstance(PT_BR);
245	
246	    public static String formatDocument(Reservation reservation) {
247	        StringBuilder doc = new StringBuilder();
248	
249	        doc.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
250	        doc.append("Hóspede: ").append(reservation.getGuestName())
251	           .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
252	        doc.append("Quarto: ").append(reservation.getRoomNumber())
253	           .append(" (").append(reservation.getRatePlanType().name()).append(")\n");
254	        doc.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
255	           .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
256	           .append(" | ").append(formatNights(reservation.getNights())).append("\n");
257	        doc.append("Diárias: ").append(formatCurrency(reservation.getSubtotal())).append("\n");
258	
259	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
260	            doc.append("Desconto: ").append(formatCurrency(reservation.getDiscount())).append("\n");
261	        }
262	
263	        doc.append("Total: ").append(formatCurrency(reservation.getTotal()));
264	
265	        return doc.toString();
266	    }
267	
268	    private static String formatCpf(String cpf) {
269	        if (cpf.length() == 11) {
270	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
271	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
272	        }
273	        return cpf;
274	    }
275	
276	    private static String formatDate(LocalDate date) {
277	        return date.format(DATE_FORMATTER);
278	    }
279	
280	    private static String formatNights(long nights) {
281	        return nights == 1 ? "1 diária" : nights + " diárias";
282	    }
283	
284	    private static String formatCurrency(BigDecimal value) {
285	        return CURRENCY_FORMATTER.format(value);
286	    }
287	}
288	package com.pousadamarealta.util;
289	
290	import com.pousadamarealta.domain.Room;
291	import java.math.BigDecimal;
292	import java.math.RoundingMode;
293	import java.time.LocalDate;
294	import java.time.temporal.ChronoUnit;
295	
296	public class PriceCalculator {
297	
298	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
299	
300	    public static BigDecimal calculateRegularSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
301	        BigDecimal subtotal = BigDecimal.ZERO;
302	        LocalDate current = checkIn;
303	
304	        while (current.isBefore(checkOut)) {
305	            BigDecimal nightPrice = room.getNightlyRate();
306	            if (isHighSeason(current)) {
307	                nightPrice = nightPrice.multiply(HIGH_SEASON_MULTIPLIER)
308	                        .setScale(2, RoundingMode.HALF_EVEN);
309	            }
310	            subtotal = subtotal.add(nightPrice);
311	            current = current.plusDays(1);
312	        }
313	
314	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
315	    }
316	
317	    private static boolean isHighSeason(LocalDate date) {
318	        int month = date.getMonthValue();
319	        int day = date.getDayOfMonth();
320	
321	        if (month == 7) {
322	            return true;
323	        }
324	
325	        if (month == 12 && day >= 15) {
326	            return true;
327	        }
328	
329	        if (month == 1 || month == 2) {
330	            return true;
331	        }
332	
333	        return false;
334	    }
335	
336	    public static long calculateNights(LocalDate checkIn, LocalDate checkOut) {
337	        return ChronoUnit.DAYS.between(checkIn, checkOut);
338	    }
339	}
