205	        if (nights != 2) {
206	            throw new InvalidRequestException("Weekend package requires exactly 2 nights");
207	        }
208	        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY) {
209	            throw new InvalidRequestException("Weekend package must start on Friday");
210	        }
211	        if (checkOut.getDayOfWeek() != DayOfWeek.SUNDAY) {
212	            throw new InvalidRequestException("Weekend package must end on Sunday");
213	        }
