  9	public class Database {
 10	    private static HikariDataSource dataSource;
 11	
 12	    public static DataSource initialize(String url, String user, String password) {
 13	        HikariConfig config = new HikariConfig();
 14	        config.setJdbcUrl(url);
 15	        config.setUsername(user);
 16	        config.setPassword(password);
 17	        config.setMaximumPoolSize(10);
 18	
 19	        dataSource = new HikariDataSource(config);
 20	        createTables();
 21	
 22	        return dataSource;
 23	    }
 24	
 25	    private static void createTables() {
 26	        String createRoomsTable = """
 27	            CREATE TABLE IF NOT EXISTS rooms (
 28	                number VARCHAR(10) PRIMARY KEY,
 29	                type VARCHAR(20) NOT NULL
 30	            )
 31	            """;
 32	
 33	        String createReservationsTable = """
 34	            CREATE TABLE IF NOT EXISTS reservations (
 35	                id BIGSERIAL PRIMARY KEY,
 36	                room_number VARCHAR(10) NOT NULL REFERENCES rooms(number),
 37	                room_type VARCHAR(20) NOT NULL,
 38	                guest_name VARCHAR(255) NOT NULL,
 39	                guest_email VARCHAR(255) NOT NULL,
 40	                guest_cpf VARCHAR(14) NOT NULL,
 41	                check_in DATE NOT NULL,
 42	                check_out DATE NOT NULL,
 43	                guests INTEGER NOT NULL,
 44	                rate_plan_type VARCHAR(30) NOT NULL,
 45	                nights BIGINT NOT NULL,
 46	                subtotal DECIMAL(10, 2) NOT NULL,
 47	                discount DECIMAL(10, 2) NOT NULL,
 48	                total DECIMAL(10, 2) NOT NULL,
 49	                status VARCHAR(20) NOT NULL,
 50	                amount_paid DECIMAL(10, 2) NOT NULL,
 51	                refund DECIMAL(10, 2)
 52	            )
 53	            """;
 54	
 55	        String createMessagesTable = """
 56	            CREATE TABLE IF NOT EXISTS messages (
 57	                id BIGSERIAL PRIMARY KEY,
 58	                channel VARCHAR(20) NOT NULL,
 59	                recipient VARCHAR(255) NOT NULL,
 60	                subject VARCHAR(500),
 61	                body TEXT NOT NULL
 62	            )
 63	            """;
 64	
 65	        try (Connection conn = dataSource.getConnection();
 66	             Statement stmt = conn.createStatement()) {
 67	
 68	            stmt.execute(createRoomsTable);
 69	            stmt.execute(createReservationsTable);
 70	            stmt.execute(createMessagesTable);
 71	
 72	        } catch (Exception e) {
 73	            throw new RuntimeException("Error creating database tables", e);
 74	        }
 75	    }
 76	
 77	    public static void shutdown() {
 78	        if (dataSource != null) {
 79	            dataSource.close();
 80	        }
 81	    }
 82	}
