169	    public Reservation save(Reservation reservation) {
170	        if (reservation.getId() == null) {
171	            return insert(reservation);
172	        } else {
173	            return update(reservation);
174	        }
175	    }
176	
177	    private Reservation insert(Reservation reservation) {
178	        String sql = """
179	            INSERT INTO reservations (room_number, room_type, guest_name, guest_email, guest_cpf,
180	                check_in, check_out, guests, rate_plan_type, nights, subtotal, discount,
181	                total, status, amount_paid, refund)
182	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
183	            """;
184	
185	        try (Connection conn = dataSource.getConnection();
186	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
187	
188	            setReservationParams(stmt, reservation);
189	            stmt.executeUpdate();
190	
191	            try (ResultSet rs = stmt.getGeneratedKeys()) {
192	                if (rs.next()) {
193	                    reservation.setId(rs.getLong(1));
194	                }
195	            }
196	
197	            return reservation;
198	        } catch (SQLException e) {
199	            throw new RuntimeException("Error saving reservation", e);
200	        }
201	    }
202	
203	    private Reservation update(Reservation reservation) {
204	        String sql = """
205	            UPDATE reservations SET status = ?, amount_paid = ?, refund = ?
206	            WHERE id = ?
207	            """;
208	
209	        try (Connection conn = dataSource.getConnection();
210	             PreparedStatement stmt = conn.prepareStatement(sql)) {
211	
212	            stmt.setString(1, reservation.getStatus().name());
213	            stmt.setBigDecimal(2, reservation.getAmountPaid());
214	            stmt.setBigDecimal(3, reservation.getRefund());
215	            stmt.setLong(4, reservation.getId());
