224	    private void setReservationParams(PreparedStatement stmt, Reservation reservation) throws SQLException {
225	        stmt.setString(1, reservation.getRoomNumber());
226	        stmt.setString(2, reservation.getRoomType().name());
227	        stmt.setString(3, reservation.getGuestName());
