234	        stmt.setLong(10, reservation.getNights());
235	        stmt.setBigDecimal(11, reservation.getSubtotal());
236	        stmt.setBigDecimal(12, reservation.getDiscount());
237	        stmt.setBigDecimal(13, reservation.getTotal());
238	        stmt.setString(14, reservation.getStatus().name());
239	        stmt.setBigDecimal(15, reservation.getAmountPaid());
