243	    public Reservation findById(Long id) {
244	        String sql = """
245	            SELECT id, room_number, room_type, guest_name, guest_email, guest_cpf, check_in, check_out,
246	                   guests, rate_plan_type, nights, subtotal, discount, total, status,
