268	    public List<Reservation> findConflicting(String roomNumber, LocalDate checkIn, LocalDate checkOut) {
269	        String sql = """
270	            SELECT id, room_number, room_type, guest_name, guest_email, guest_cpf, check_in, check_out,
271	                   guests, rate_plan_type, nights, subtotal, discount, total, status,
272	                   amount_paid, refund
273	            FROM reservations
274	            WHERE room_number = ?
275	              AND status != 'CANCELLED'
276	              AND check_in < ?
