319	            stmt.setDate(2, Date.valueOf(night));
320	
321	            try (ResultSet rs = stmt.executeQuery()) {
322	                while (rs.next()) {
323	                    reservations.add(mapReservation(rs));
324	                }
325	            }
326	        } catch (SQLException e) {
327	            throw new RuntimeException("Error fetching reservations by night", e);
328	        }
