333	    public List<Reservation> findByMonth(YearMonth month) {
334	        String sql = """
335	            SELECT id, room_number, room_type, guest_name, guest_email, guest_cpf, check_in, check_out,
336	                   guests, rate_plan_type, nights, subtotal, discount, total, status,
337	                   amount_paid, refund
338	            FROM reservations
339	            WHERE check_in >= ?
340	              AND check_in < ?
341	              AND (amount_paid > 0 OR refund > 0)
342	            ORDER BY check_in, id
343	            """;
344	
345	        List<Reservation> reservations = new ArrayList<>();
346	
347	        try (Connection conn = dataSource.getConnection();
348	             PreparedStatement stmt = conn.prepareStatement(sql)) {
349	
350	            LocalDate start = month.atDay(1);
351	            LocalDate end = month.plusMonths(1).atDay(1);
352	
353	            stmt.setDate(1, Date.valueOf(start));
354	            stmt.setDate(2, Date.valueOf(end));
355	
356	            try (ResultSet rs = stmt.executeQuery()) {
357	                while (rs.next()) {
358	                    reservations.add(mapReservation(rs));
359	                }
360	            }
361	        } catch (SQLException e) {
362	            throw new RuntimeException("Error fetching reservations by month", e);
363	        }
364	
365	        return reservations;
366	    }
367	
368	    private Reservation mapReservation(ResultSet rs) throws SQLException {
369	        return new Reservation(
370	            rs.getLong("id"),
371	            rs.getString("room_number"),
372	            RoomType.valueOf(rs.getString("room_type")),
373	            rs.getString("guest_name"),
374	            rs.getString("guest_email"),
375	            rs.getString("guest_cpf"),
376	            rs.getDate("check_in").toLocalDate(),
377	            rs.getDate("check_out").toLocalDate(),
378	            rs.getInt("guests"),
379	            RatePlanType.valueOf(rs.getString("rate_plan_type")),
380	            rs.getLong("nights"),
381	            rs.getBigDecimal("subtotal"),
382	            rs.getBigDecimal("discount"),
383	            rs.getBigDecimal("total"),
384	            ReservationStatus.valueOf(rs.getString("status")),
385	            rs.getBigDecimal("amount_paid"),
386	            rs.getBigDecimal("refund")
387	        );
388	    }
389	}
