     9	class ReservationTest {
    10	
    11	    @Test
    12	    void shouldCreateReservationWithStandardPlan() {
    13	        Room room = new Room("101", RoomType.STANDARD);
    14	        LocalDate checkIn = LocalDate.of(2027, 3, 10);
    15	        LocalDate checkOut = LocalDate.of(2027, 3, 12);
    16	
    17	        Reservation reservation = Reservation.create(
    18	            "101", room, "João Silva", "joao@example.com", "12345678901",
    19	            checkIn, checkOut, 2, RatePlanType.STANDARD, null
    20	        );
    21	
    22	        assertEquals(ReservationStatus.PENDING, reservation.getStatus());
    23	        assertEquals(2, reservation.getNights());
    24	        assertEquals(new BigDecimal("499.80"), reservation.getSubtotal());
    25	        assertEquals(BigDecimal.ZERO, reservation.getDiscount());
    26	        assertEquals(new BigDecimal("499.80"), reservation.getTotal());
    27	        assertEquals(RoomType.STANDARD, reservation.getRoomType());
    28	    }
    29	
    30	    @Test
    31	    void shouldConfirmReservation() {
    32	        Room room = new Room("101", RoomType.STANDARD);
    33	        LocalDate checkIn = LocalDate.of(2027, 3, 10);
    34	        LocalDate checkOut = LocalDate.of(2027, 3, 12);
    35	
    36	        Reservation reservation = Reservation.create(
    37	            "101", room, "João Silva", "joao@example.com", "12345678901",
    38	            checkIn, checkOut, 2, RatePlanType.STANDARD, null
    39	        );
    40	
    41	        reservation.confirm();
    42	
    43	        assertEquals(ReservationStatus.CONFIRMED, reservation.getStatus());
    44	        assertEquals(reservation.getTotal(), reservation.getAmountPaid());
    45	    }
    46	
    47	    @Test
    48	    void shouldNotAllowConfirmingNonPendingReservation() {
    49	        Room room = new Room("101", RoomType.STANDARD);
    50	        LocalDate checkIn = LocalDate.of(2027, 3, 10);
    51	        LocalDate checkOut = LocalDate.of(2027, 3, 12);
    52	
    53	        Reservation reservation = Reservation.create(
    54	            "101", room, "João Silva", "joao@example.com", "12345678901",
    55	            checkIn, checkOut, 2, RatePlanType.STANDARD, null
    56	        );
    57	        reservation.confirm();
    58	
    59	        assertThrows(OperationNotAllowedException.class, () -> {
    60	            reservation.confirm();
    61	        });
    62	    }
    63	
    64	    @Test
    65	    void shouldCancelReservationWithFullRefund() {
    66	        Room room = new Room("101", RoomType.STANDARD);
    67	        LocalDate checkIn = LocalDate.of(2027, 3, 10);
